55	    /**
56	     * 设备拉取：已存在任务直接返回；否则仅当型号与当前版本匹配、分桶号小于比例且发布单 ACTIVE 时创建。
57	     * PAUSED 时不创建新任务，已有任务仍可查看与回执。
58	     */
59	    public PullResponse pull(String deviceId, String requestId) {
60	        String fingerprint = String.join("|", "task.pull", deviceId);
61	        return idempotency.execute(requestId, "task.pull", fingerprint, () -> {
62	            Device device = deviceService.findDevice(deviceId);
63	            var activeOrder = releaseRepository.findActiveByModel(device.model());
64	            if (activeOrder.isEmpty()) {
65	                return new PullResponse(null);
66	            }
67	            ReleaseOrder order = releaseRepository.findByIdForUpdate(activeOrder.get().id())
68	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
69	            var existing = taskRepository.findByReleaseAndDevice(order.id(), deviceId);
70	            if (existing.isPresent()) {
71	                return new PullResponse(TaskView.of(existing.get(), order));
72	            }
73	            if (order.status() != ReleaseStatus.ACTIVE
74	                    || !device.currentVersion().equals(order.fromVersion())
75	                    || device.bucketNo() >= order.ratio()) {
76	                return new PullResponse(null);
77	            }
78	            long taskId;
79	            try {
80	                taskId = taskRepository.insert(order.id(), deviceId);
81	            } catch (DuplicateKeyException e) {
82	                RolloutTask task = taskRepository.findByReleaseAndDevice(order.id(), deviceId)
83	                        .orElseThrow(() -> new IllegalStateException("任务唯一约束冲突后未找到任务"));
84	                return new PullResponse(TaskView.of(task, order));
85	            }
86	            RolloutTask task = taskRepository.findById(taskId)
87	                    .orElseThrow(() -> new IllegalStateException("任务创建后读取失败"));
88	            return new PullResponse(TaskView.of(task, order));
89	        }, PullResponse.class);
90	    }
91	
92	    /**
93	     * 回执：首次回执终结任务并计入完成时所在监控轮次，仅 SUCCESS 更新设备当前版本；
94	     * 同结果重复成功（不重复计数），改结果 409；已取消任务的后到回执 409 且不更新设备版本。
95	     * 样本达到下限且失败率越限时，同事务将仍为 ACTIVE 的发布单原子转为 PAUSED 并落暂停记录。
96	     */
97	    public TaskView receipt(long taskId, ReceiptRequest request) {
98	        String fingerprint = String.join("|", "task.receipt", String.valueOf(taskId), request.result().name());
99	        return idempotency.execute(request.requestId(), "task.receipt", fingerprint, () -> {
100	            RolloutTask snapshot = taskRepository.findById(taskId)
101	                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
102	            ReleaseOrder lockedOrder = releaseRepository.findByIdForUpdate(snapshot.releaseId())
103	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
104	            RolloutTask task = taskRepository.findByIdForUpdate(taskId)
105	                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
106	            return switch (task.status()) {
107	                case PENDING -> {
108	                    taskRepository.complete(taskId, request.result());
109	                    releaseRepository.incrementRoundStats(snapshot.releaseId(), request.result());
110	                    if (request.result() == ReceiptResult.SUCCESS) {
111	                        deviceRepository.updateCurrentVersion(task.deviceId(), lockedOrder.toVersion());
112	                    }
113	                    ReleaseOrder updated = releaseRepository.findById(snapshot.releaseId()).orElseThrow();
114	                    pauseIfThresholdReached(updated, taskId);
115	                    yield TaskView.of(taskRepository.findById(taskId).orElseThrow(), updated);
116	                }
117	                case SUCCESS, FAILED -> {
118	                    if (task.firstResult() == request.result()) {
119	                        yield TaskView.of(task, lockedOrder);
120	                    }
121	                    throw ApiException.conflict("RECEIPT_RESULT_CONFLICT",
122	                            "任务已终结为 " + task.firstResult() + "，不能改为 " + request.result());
123	                }
124	                case CANCELLED -> throw ApiException.conflict("TASK_CANCELLED", "任务已取消，回执不再受理");
125	            };
126	        }, TaskView.class);
127	    }
128	
129	    /**
130	     * 样本数达到下限且 FAILED×100 >= 样本数×阈值 时，将仍为 ACTIVE 的发布单原子转为 PAUSED。
131	     * 调用方持有发布单行锁，并发回执串行通过，每轮至多生成一条暂停记录。
132	     */
133	    private void pauseIfThresholdReached(ReleaseOrder order, long triggerTaskId) {
134	        if (order.status() != ReleaseStatus.ACTIVE) {
135	            return;
136	        }
137	        int samples = order.roundSuccess() + order.roundFailed();
138	        if (samples < order.sampleFloor()) {
139	            return;
140	        }
141	        if ((long) order.roundFailed() * 100 < (long) samples * order.failureThresholdPercent()) {
142	            return;
143	        }
144	        if (releaseRepository.pauseIfActive(order.id()) == 1) {
145	            pauseRecordRepository.insert(order.id(), order.monitorRound(), triggerTaskId,
146	                    order.roundSuccess(), order.roundFailed(), Instant.now(clock).toString());
147	        }
148	    }
149	
150	    public TaskListResponse listByRelease(long releaseId, TaskStatus statusFilter) {
151	        ReleaseOrder order = releaseService.findOrder(releaseId);
152	        List<TaskView> tasks = taskRepository.findByRelease(releaseId, statusFilter).stream()
153	                .map(task -> TaskView.of(task, order))
154	                .toList();
155	        return new TaskListResponse(tasks);
156	    }
157	}
