**revoke**:
```java
public TaskView revoke(long taskId, String requestId) {
    String fingerprint = String.join("|", "task.revoke", String.valueOf(taskId));
    return idempotency.execute(requestId, "task.revoke", fingerprint, () -> {
        RolloutTask snapshot = taskRepository.findById(taskId).orElseThrow(404);
        ReleaseOrder lockedOrder = releaseRepository.findByIdForUpdate(snapshot.releaseId()).orElseThrow(404);
        RolloutTask task = taskRepository.findByIdForUpdate(taskId).orElseThrow(404);
        return switch (task.status()) {
            case PENDING, INSTALLABLE, INTEGRITY_FAILED -> {
                taskRepository.updateStatus(taskId, TaskStatus.CANCELLED);
                if (lockedOrder.hasManifest()) finalize current attempt CANCELLED;
                yield viewOf(reloaded, lockedOrder);
            }
            case CANCELLED -> viewOf(task, lockedOrder); // 已取消：幂等返回当前状态
            case SUCCESS, FAILED -> throw 409 TASK_ALREADY_FINAL;
        };
    }, TaskView.class);
}
