private TaskView viewOf(RolloutTask task, ReleaseOrder order) {
    if (!order.hasManifest()) return TaskView.of(task, order);
    int attemptNo = attemptRepository.findCurrent(task.id()).map(TaskAttempt::attemptNo).orElse(0);
    int received = chunkReceiptRepository.countByTaskAndAttempt(task.id(), attemptNo);
    return TaskView.of(task, order, attemptNo, received);
