private record Context(RolloutTask task, ReleaseOrder order, TaskAttempt attempt, List<ChunkEntry> manifest) {}

private Context lockContext(long taskId) {
    RolloutTask snapshot = taskRepository.findById(taskId).orElseThrow(404 TASK_NOT_FOUND);
    ReleaseOrder order = releaseRepository.findByIdForUpdate(snapshot.releaseId()).orElseThrow(404);
    RolloutTask task = taskRepository.findByIdForUpdate(taskId).orElseThrow(404);
    if (!order.hasManifest()) throw 409 MANIFEST_NOT_REGISTERED "该发布单未登记分片清单，不支持分片接收";
    TaskAttempt attempt = attemptRepository.findCurrent(taskId).orElseThrow(illegal state);
    List<ChunkEntry> manifest = chunkManifestRepository.findByRelease(order.id());
    return new Context(task, order, attempt, manifest);
}

private void ensureReceivable(RolloutTask task) {
    switch (task.status()) {
        case PENDING -> {}
        case INSTALLABLE -> throw 409 TASK_ALREADY_INSTALLABLE "任务已可安装，当前代次分片接收已关闭"
        case INTEGRITY_FAILED -> throw 409 TASK_INTEGRITY_FAILED "本尝试已完整性失败，需重新拉取建立新尝试"
        case SUCCESS, FAILED -> throw 409 TASK_ALREADY_FINAL
        case CANCELLED -> throw 409 TASK_CANCELLED
    }
}
```

receiveChunk:
```java
public TaskView receiveChunk(long taskId, SubmitChunkRequest request) {
    String fingerprint = String.join("|", "task.chunk", String.valueOf(taskId),
            String.valueOf(request.chunkIndex()), request.digest());
    return idempotency.execute(request.requestId(), "task.chunk", fingerprint, () -> {
        Context ctx = lockContext(taskId);
        ensureReceivable(ctx.task());
        int index = request.chunkIndex();
        String now = Instant.now(clock).toString();
        if (index >= ctx.order().chunkCount()) {  // negative excluded by @Min(0)
            return failAttempt(ctx, IntegrityFailureReason.INDEX_OUT_OF_RANGE, index, null,
                    request.digest(), "分片序号超出清单范围：要求 0.." + (chunkCount-1) + "，实际 " + index, now);
        }
        String expected = manifest digest at index;
        var existing = chunkReceiptRepository.find(taskId, attemptNo, index);
        if (existing.isPresent()) {
            if (existing.get().digest().equals(request.digest())) {
                return viewOf(ctx, "重复分片幂等确认"); // no change
            }
            return failAttempt(ctx, DIGEST_MISMATCH, index, expected, request.digest(),
                    "分片序号重复且摘要不一致：已接收 " + existing digest + "，本次 " + request.digest(), now);
        }
        if (!expected.equals(request.digest())) {
            return failAttempt(ctx, DIGEST_MISMATCH, index, expected, request.digest(), "分片摘要与清单不匹配", now);
        }
        chunkReceiptRepository.insert(taskId, attemptNo, index, request.digest(), now);
        integrityEventRepository.insert(CHUNK_ACCEPTED event...);
        int received = count + 1... 
        if (received == chunkCount) → markInstallable(ctx, now)
        return viewOf(...);
    }, TaskView.class);
}
```

failAttempt: insert INTEGRITY_FAILED event, task → INTEGRITY_FAILED, attempt finalize INTEGRITY_FAILED, return viewOf.

markInstallable: compute aggregate from manifest (== received), insert INSTALLABLE event with chunkCount, aggregateDigest, packageDigest; task → INSTALLABLE; attempt status INSTALLABLE (not finalized — finalized only at terminal).

receiveBatch:
```java
String canonical = chunks sorted "index:digest" joined + complete flag;
fingerprint = "task.chunks.batch|" + taskId + "|" + Digests.sha256Hex(canonical);
execute {
    Context ctx = lockContext(taskId);
    ensureReceivable(ctx.task());
    String now = ...;
    // 先校验完整最终集合：任一失败不写入任何接收记录
    // 1. 请求内重复序号
    Map<Integer, String> byIndex = new LinkedHashMap<>();
    for (chunk : request.chunks()) {
        if (byIndex.putIfAbsent(index, digest) != null) → failAttempt(DUPLICATE_INDEX, index, expectedOrNull, digest, "同一请求内分片序号重复: " + index)
    }
    // 2. 逐个校验范围、与已接收的一致性、与清单的一致性
    List<ChunkEntry> toInsert = new ArrayList<>();
    for (entry : byIndex entries sorted) {
        if (index >= chunkCount) → failAttempt(INDEX_OUT_OF_RANGE, ...)
        existing = receipt find
        if (existing present) {
            if (!existing.digest.equals(digest)) → failAttempt(DUPLICATE_INDEX? DIGEST_MISMATCH...)
            else skip (idempotent)
        } else {
            expected = manifest[index]
            if (!expected.equals(digest)) → failAttempt(DIGEST_MISMATCH, index, expected, digest, ...)
            toInsert.add(...)
        }
    }
    // 3. 若声明最终集合，校验完整性
    int totalAfter = receivedCount + toInsert.size();
    if (request.complete() && totalAfter != chunkCount) {
        missing indices computed;
        → failAttempt(INCOMPLETE_SET, null, null, null, "缺失分片序号: [...]，实际 " + totalAfter + "/" + chunkCount)
    }
    // 全部校验通过才写入
    for (insert) { chunkReceiptRepository.insert; event CHUNK_ACCEPTED; }
    if (totalAfter == chunkCount) markInstallable;
    return viewOf;
}
```

Note: `request.complete()` — Boolean complete flag; default false. In SubmitChunksBatchRequest: `Boolean complete` → treat null as false. I'll use `boolean complete()` primitive? JSON missing → false for primitive boolean. Jackson maps missing to false for primitives. Use primitive boolean.

