private TaskView markInstallable(Context ctx, String now) {
    String aggregate = Digests.aggregateOf(manifest digests in order);
    // 单分片均已与清单比对，聚合必然等于 packageDigest；防御性校验
    if (!aggregate.equals(ctx.order().packageDigest())) {
        return failAttempt(ctx, AGGREGATE_MISMATCH, null, null, null, "聚合摘要不匹配", now);
    }
    integrityEventRepository.insert(INSTALLABLE event with chunkCount, aggregate, packageDigest, now);
    taskRepository.updateStatus(taskId, INSTALLABLE);
    attemptRepository.updateStatus(taskId, attemptNo, INSTALLABLE, null);
    return viewOf(task reloaded, order);
}
