 * 不留下部分可安装状态。同任务同代次同序号并发提交由唯一约束保证最多一笔成功。
 * INTEGRITY_FAILED 不计入设备执行失败率；重新拉取只可为未安装任务建立新尝试代次，旧证据保留。
 */
@Service
public class IntegrityService {

    private final TaskRepository taskRepository;
    private final ReleaseRepository releaseRepository;
    private final ChunkManifestRepository manifestRepository;
    private final ChunkReceiptRepository receiptRepository;
    private final TaskAttemptRepository attemptRepository;
    private final IntegrityEventRepository eventRepository;
    private final TaskService taskService;
    private final IdempotencyService idempotency;
    private final Clock clock;

    public IntegrityService(TaskRepository taskRepository, ReleaseRepository releaseRepository,
                            ChunkManifestRepository manifestRepository,
                            ChunkReceiptRepository receiptRepository,
                            TaskAttemptRepository attemptRepository,
                            IntegrityEventRepository eventRepository,
                            TaskService taskService, IdempotencyService idempotency, Clock clock) {
        this.taskRepository = taskRepository;
        this.releaseRepository = releaseRepository;
        this.manifestRepository = manifestRepository;
        this.receiptRepository = receiptRepository;
        this.attemptRepository = attemptRepository;
        this.eventRepository = eventRepository;
        this.taskService = taskService;
        this.idempotency = idempotency;
        this.clock = clock;
    }

    /**
     * 批量接收分片摘要并裁决。整体成功进入 INSTALLABLE；任一校验失败转为 INTEGRITY_FAILED。
     */
    public TaskView receiveChunks(long taskId, String requestId, List<ChunkDigestInput> chunks) {
        if (chunks == null || chunks.isEmpty()) {
            throw ApiException.badRequest("EMPTY_BATCH", "分片接收批次不能为空");
        }
        String sortedFingerprint = chunks.stream()
                .sorted(java.util.Comparator.comparing(ChunkDigestInput::chunkIndex)
                        .thenComparing(ChunkDigestInput::digest))
                .map(c -> c.chunkIndex() + ":" + c.digest())
                .collect(Collectors.joining(","));
        String fingerprint = String.join("|", "task.chunks", String.valueOf(taskId), sortedFingerprint);
        return idempotency.execute(requestId, "task.chunks", fingerprint, () -> {
            RolloutTask snapshot = taskRepository.findById(taskId)
                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
            ReleaseOrder order = releaseRepository.findByIdForUpdate(snapshot.releaseId())
                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
            if (!order.hasManifest()) {
                throw ApiException.conflict("MANIFEST_NOT_REGISTERED",
                        "发布单未登记分片清单，不支持分片接收: " + order.id());
            }
            RolloutTask task = taskRepository.findByIdForUpdate(taskId)
                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
            TaskAttempt attempt = attemptRepository.findCurrent(taskId)
                    .orElseThrow(() -> new IllegalStateException("清单任务缺少尝试代次: " + taskId));
            if (task.status() == TaskStatus.SUCCESS || task.status() == TaskStatus.FAILED) {
                throw ApiException.conflict("TASK_ALREADY_FINAL",
                        "任务已终结为 " + task.status() + "，不再接收分片");
            }
            if (task.status() == TaskStatus.CANCELLED) {
                throw ApiException.conflict("TASK_CANCELLED", "任务已取消，不再接收分片");
            }
            if (task.status() == TaskStatus.INSTALLABLE) {
                throw ApiException.conflict("TASK_ALREADY_INSTALLABLE",
                        "任务已完成完整性核验并进入可安装状态，请勿重复提交");
            }

            String now = Instant.now(clock).toString();
            Failure failure = evaluate(order, attempt, chunks, now);
            if (failure != null) {
                // 完整性失败：固化失败事件，任务与当前代次转 INTEGRITY_FAILED；接收证据不写入，无半成品。
                eventRepository.insert(failure.event);
                attemptRepository.updateStatus(taskId, attempt.attemptNo(),
                        TaskStatus.INTEGRITY_FAILED, now);
                taskRepository.updateStatus(taskId, TaskStatus.INTEGRITY_FAILED);
                throw ApiException.conflict(failure.event.reason().name(), failure.detail);
            }

            // 校验通过：先固化全部接收证据与 CHUNK_ACCEPTED 事件，再落 INSTALLABLE 判定事件与状态。
            Map<Integer, String> byIndex = new HashMap<>();
            for (ChunkDigestInput chunk : chunks) {
                byIndex.put(chunk.chunkIndex(), chunk.digest());
            }
            for (ChunkEntry entry : manifestRepository.findByRelease(order.id())) {
                String digest = byIndex.get(entry.chunkIndex());
                receiptRepository.insert(taskId, attempt.attemptNo(), entry.chunkIndex(), digest, now);
                eventRepository.insert(new IntegrityEvent(0, taskId, attempt.attemptNo(), order.id(),
                        IntegrityEventType.CHUNK_ACCEPTED, entry.chunkIndex(), entry.digest(), digest,
                        null, null, null, null, null, now));
            }
            String aggregate = Digests.aggregateOf(
                    byIndex.entrySet().stream()
                            .sorted(Map.Entry.comparingByKey())
                            .map(Map.Entry::getValue)
                            .toList());
            eventRepository.insert(new IntegrityEvent(0, taskId, attempt.attemptNo(), order.id(),
                    IntegrityEventType.INSTALLABLE, null, null, null,
                    order.chunkCount(), aggregate, order.packageDigest(), null, null, now));
            attemptRepository.updateStatus(taskId, attempt.attemptNo(), TaskStatus.INSTALLABLE, null);
            taskRepository.updateStatus(taskId, TaskStatus.INSTALLABLE);

            ReleaseOrder fresh = releaseRepository.findById(order.id()).orElseThrow();
            return taskService.detail(taskId);
        }, TaskView.class);
    }

    /**
     * 校验完整最终集合：历史已接收 + 本批次。返回 null 表示通过；否则返回失败描述。
     * 校验项：格式、序号范围、批内/与历史重复、缺失序号、聚合摘要。
     */
    private Failure evaluate(ReleaseOrder order, TaskAttempt attempt, List<ChunkDigestInput> batch, String now) {
        int required = order.chunkCount();
        Set<Integer> batchIndices = new HashSet<>();
        for (ChunkDigestInput chunk : batch) {
            Integer index = chunk.chunkIndex();
            String digest = chunk.digest();
            if (index == null || digest == null) {
                throw ApiException.badRequest("INVALID_CHUNK", "分片条目缺少 chunkIndex 或 digest");
            }
            if (!Digests.isSha256Hex(digest)) {
                return fail(order, attempt, IntegrityFailureReason.DIGEST_MISMATCH, index,
                        null, digest, required, null,
                        "分片 " + index + " 摘要格式不合法：要求64位小写十六进制，实际 " + digest, now);
            }
            if (index < 0 || index >= required) {
                return fail(order, attempt, IntegrityFailureReason.INDEX_OUT_OF_RANGE, index,
                        null, digest, required, null,
                        "分片序号超出范围：要求 0.." + (required - 1) + "，实际 " + index
                                + "（要求分片总数 " + required + "）", now);
            }
            if (!batchIndices.add(index)) {
                return fail(order, attempt, IntegrityFailureReason.DUPLICATE_INDEX, index,
                        null, digest, required, null,
                        "同一批次内分片序号重复: " + index, now);
            }
        }

        List<ChunkReceipt> existing = receiptRepository.findByTaskAndAttempt(attempt.taskId(), attempt.attemptNo());
        Set<Integer> finalIndices = new HashSet<>();
        existing.forEach(r -> finalIndices.add(r.chunkIndex()));
        Map<Integer, String> finalDigests = new HashMap<>();
        existing.forEach(r -> finalDigests.put(r.chunkIndex(), r.digest()));
        for (ChunkDigestInput chunk : batch) {
            if (!finalIndices.add(chunk.chunkIndex())) {
                return fail(order, attempt, IntegrityFailureReason.DUPLICATE_INDEX, chunk.chunkIndex(),
                        finalDigests.get(chunk.chunkIndex()), chunk.digest(), required, null,
                        "分片 " + chunk.chunkIndex() + " 在当前尝试代次已接收，不能重复提交", now);
            }
            finalDigests.put(chunk.chunkIndex(), chunk.digest());
        }

        List<ChunkEntry> manifest = manifestRepository.findByRelease(order.id());
        for (ChunkEntry entry : manifest) {
            String received = finalDigests.get(entry.chunkIndex());
            if (received == null) {
                // 集合尚未完整时不立即判失败：设备可继续补交；仅当本批次声称补齐却仍有缺口才进入终态判定。
                // 这里按“先校验完整最终集合”的契约：最终集合不完整直接 INTEGRITY_FAILED。
                List<Integer> missing = new ArrayList<>();
                for (ChunkEntry e : manifest) {
                    if (!finalIndices.contains(e.chunkIndex())) {
                        missing.add(e.chunkIndex());
                    }
                }
                return fail(order, attempt, IntegrityFailureReason.INCOMPLETE_SET, null,
                        null, null, required, null,
                        "最终分片集合不完整：要求 " + required + " 个，实际 " + finalIndices.size()
                                + " 个，缺失 " + missing.size() + " 个，缺失序号 " + missing, now);
            }
            if (!entry.digest().equals(received)) {
                return fail(order, attempt, IntegrityFailureReason.DIGEST_MISMATCH, entry.chunkIndex(),
                        entry.digest(), received, required, null,
                        "分片 " + entry.chunkIndex() + " 摘要不匹配：期望 " + entry.digest()
                                + "，实际 " + received, now);
            }
        }

        String aggregate = Digests.aggregateOf(manifest.stream().map(ChunkEntry::digest).toList());
        if (!aggregate.equals(order.packageDigest())) {
            return fail(order, attempt, IntegrityFailureReason.AGGREGATE_MISMATCH, null,
                    order.packageDigest(), null, required, aggregate,
                    "聚合摘要不匹配：登记值 " + order.packageDigest() + "，聚合计算值 " + aggregate, now);
        }
        return null;
    }

    private Failure fail(ReleaseOrder order, TaskAttempt attempt, IntegrityFailureReason reason,
                         Integer chunkIndex, String expectedDigest, String receivedDigest,
                         Integer chunkCount, String aggregateDigest, String detail, String now) {
        IntegrityEvent event = new IntegrityEvent(0, attempt.taskId(), attempt.attemptNo(), order.id(),
                IntegrityEventType.INTEGRITY_FAILED, chunkIndex, expectedDigest, receivedDigest,
                chunkCount, aggregateDigest, order.packageDigest(), reason, detail, now);
        return new Failure(event, detail);
    }

    private record Failure(IntegrityEvent event, String detail) {
    }
}

