                    return IntegrityService.<TaskView>failure(order, attempt,
                            IntegrityFailureReason.INDEX_OUT_OF_RANGE, index, null, digest,
                            "分片序号超出范围：要求 0.." + (order.chunkCount() - 1)
                                    + "（要求分片总数 " + order.chunkCount() + "），实际 " + index, now);
                }
