            }
            return IdempotencyService.AdjudicatedOutcome.ok(taskService.detail(taskId));
        }, TaskView.class);
    }

    /**
     * 构造已提交的完整性失败裁决：固化失败事件、任务与代次转 INTEGRITY_FAILED，错误不占幂等键。
     */
    private static <T> IdempotencyService.AdjudicatedOutcome<T> failure(
            ReleaseOrder order, TaskAttempt attempt, IntegrityFailureReason reason,
            Integer chunkIndex, String expectedDigest, String receivedDigest,
            String detail, String now) {
        IntegrityEvent event = new IntegrityEvent(0, attempt.taskId(), attempt.attemptNo(), order.id(),
                IntegrityEventType.INTEGRITY_FAILED, chunkIndex, expectedDigest, receivedDigest,
                order.chunkCount(), null, order.packageDigest(), reason, detail, now);
        // 通过事件仓库落库需要实例方法；此处仅构造结果，落库由接收主流程统一完成。
