     */
    public List<IntegrityEvent> findByTask(long taskId, String fromUtc, String toUtc) {
        StringBuilder sql = new StringBuilder("SELECT " + COLUMNS + " FROM integrity_event WHERE task_id = ?");
        List<Object> args = new ArrayList<>();
