        mockMvc.perform(get("/api/releases/" + releaseId + "/manifest"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("MANIFEST_NOT_REGISTERED"));

        // 补登成功，清单按序号规范排序返回
